using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using NAudio.CoreAudioApi;using WinhancedBridge;
[ComImport,Guid("F8679F50-850A-41CF-9C72-430F290290C8"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]interface IEndpointPolicy{void Slot1();void Slot2();void Slot3();void Slot4();void Slot5();void Slot6();void Slot7();void Slot8();void Slot9();void Slot10();void SetDefaultEndpoint([MarshalAs(UnmanagedType.LPWStr)]string id,int role);}
class NovaDevices{
 static void Main(){try{var p=JObject.Parse(Console.In.ReadToEnd());Console.Write(JsonConvert.SerializeObject(new{ok=true,result=Run(p)}));}catch(Exception ex){Console.Write(JsonConvert.SerializeObject(new{ok=false,error=ex.GetBaseException().Message}));}}
 static object Run(JObject p){var kind=(string)p["kind"];var action=(string)p["operation"]??"list";if(kind=="wifi"){using(var adapter=new WifiAdapter()){var networks=adapter.List(action=="scan");if(action=="connect"||action=="disconnect"){var target=networks.FirstOrDefault(n=>n.Name==(string)p["name"]);if(target==null)throw new Exception("Rete non più disponibile. Aggiorna le reti.");if(action=="connect")adapter.Connect(target,(string)p["password"]??"");else adapter.Disconnect(target);return "Richiesta inviata. Aggiorna per verificare lo stato.";}return networks.Select(n=>new{name=n.Name,signal=n.Signal,connected=n.Connected,secure=n.Secure,saved=!string.IsNullOrEmpty(n.Profile)}).ToArray();}}
 if(kind=="bluetooth"){var devices=BluetoothNative.Devices(action=="scan");if(action=="pair"||action=="unpair"){var target=devices.First(d=>d.Address.ToString()==(string)p["address"]);if(action=="pair")BluetoothNative.Pair(IntPtr.Zero,target);else BluetoothNative.Unpair(target);return "Operazione Bluetooth completata.";}return devices.Select(d=>new{name=d.Name,address=d.Address.ToString(),connected=d.Connected!=0,paired=d.Authenticated!=0}).ToArray();}
 if(kind=="audio"){using(var enumerator=new MMDeviceEnumerator()){var devices=enumerator.EnumerateAudioEndPoints(DataFlow.Render,DeviceState.Active);if(action=="output"){var target=devices.First(d=>d.ID==(string)p["id"]);var policy=(IEndpointPolicy)Activator.CreateInstance(Type.GetTypeFromCLSID(new Guid("870AF99C-171D-4F9E-AF0D-E63DF40C2BC9")));try{for(int i=0;i<3;i++)policy.SetDefaultEndpoint(target.ID,i);}finally{Marshal.ReleaseComObject(policy);}return "Uscita audio aggiornata.";}if(action=="volume"){var target=devices.First(d=>d.ID==(string)p["id"]);var level=Math.Max(0,Math.Min(1,(double?)p["value"]??0));if(p["session"]!=null){var s=target.AudioSessionManager.Sessions[(int)p["session"]];if(s.GetProcessID!=(uint)p["pid"])throw new Exception("Sessione cambiata. Aggiorna il mixer.");s.SimpleAudioVolume.Volume=(float)level;}else target.AudioEndpointVolume.MasterVolumeLevelScalar=(float)level;return "Volume aggiornato.";}string current="";try{current=enumerator.GetDefaultAudioEndpoint(DataFlow.Render,Role.Multimedia).ID;}catch{}return new{current,devices=devices.Select(d=>new{id=d.ID,name=d.FriendlyName,volume=d.AudioEndpointVolume.MasterVolumeLevelScalar}).ToArray(),sessions=devices.SelectMany(d=>Enumerable.Range(0,d.AudioSessionManager.Sessions.Count).Select(i=>{var s=d.AudioSessionManager.Sessions[i];string name=s.DisplayName;try{name=s.IsSystemSoundsSession?"Suoni di sistema":System.Diagnostics.Process.GetProcessById((int)s.GetProcessID).ProcessName;}catch{}return new{id=d.ID,index=i,pid=s.GetProcessID,name=name??"Applicazione",device=d.FriendlyName,volume=s.SimpleAudioVolume.Volume};})).ToArray()};}}
 throw new Exception("Dispositivo non supportato.");}
}
